// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ITetherToken {
    function balanceOf(address who) external view returns (uint);
    function issue(uint amount) external;
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for fork test
        vm.label(TARGET, "TetherToken (USDT)");
        // Store our address as the owner at slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        // Now we are the owner, mint tokens to ourselves
        ITetherToken target = ITetherToken(TARGET);

        uint256 targetInitialBalance = target.balanceOf(attacker);
        console.log("Initial balance:", targetInitialBalance);

        // Mint 1,000,000 USDT (6 decimals)
        target.issue(1_000_000 * 10**6);

        uint256 targetFinalBalance = target.balanceOf(attacker);
        console.log("Final balance:", targetFinalBalance);

        // Verify balance increased
        assertGt(targetFinalBalance, targetInitialBalance, "Balance should have increased");
        console.log("Success: Minted", targetFinalBalance - targetInitialBalance, "tokens");

        uint256 finalBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
